<link rel="stylesheet" href="<?=e(asset('css/publishing-desk.css'))?>">
<main class="desk desk-workspace"><header class="desk-hero"><div><p class="desk-kicker">Private correspondence</p><h1>Email & response log</h1><p>Follow website enquiries from receipt to acknowledgement and recorded reply. Draft creation and provider acceptance are not proof of inbox delivery.</p></div><a class="desk-button" href="<?=url('/write/communication/mail')?>">Connected Gmail inbox / drafts</a></header>
<?php if($error):?><p class="desk-alert" role="alert"><?=e($error)?></p><?php endif;?>
<nav class="desk-tabs" aria-label="Correspondence views"><?php foreach(['received'=>'Received enquiries','outgoing'=>'Outgoing email','drafts'=>'Gmail draft activity']as$key=>$label):?><a href="?view=<?=e($key)?>" <?=$view===$key?'aria-current="page"':''?>><?=e($label)?></a><?php endforeach;?></nav>
<?php if($view!=='drafts'):?><form method="get" class="desk-actions"><input type="hidden" name="view" value="<?=e($view)?>"><label class="desk-field"><span><?=$view==='outgoing'?'Email log ID':'Reference, name or email'?></span><input name="q" value="<?=e($search)?>" maxlength="120" <?=$view==='outgoing'?'inputmode="numeric"':''?>></label><?php if($view==='outgoing'):?><label class="desk-field"><span>Status</span><select name="status"><option value="">All states</option><?php foreach(['pending','sending','sent','ambiguous','suppressed','failed','cancelled']as$state):?><option value="<?=e($state)?>" <?=$status===$state?'selected':''?>><?=e(correspondence_status($state))?></option><?php endforeach;?></select></label><?php endif;?><button class="desk-button primary">Filter log</button></form><?php endif;?>
<p class="desk-note"><?=(int)$total?> records. Historical messages retain their original content; new system messages use the updated logo and brand colours. Original incoming third-party emails are not rewritten.</p>
<div class="desk-table-wrap"><table><thead><tr><?php if($view==='received'):?><th>Received / reference</th><th>Sender</th><th>Acknowledgement</th><th>Reply record</th><?php elseif($view==='outgoing'):?><th>ID / created</th><th>Recipient / subject</th><th>Transport state</th><th>Evidence</th><?php else:?><th>Time / account</th><th>Recipient / subject</th><th>Draft state</th><?php endif;?></tr></thead><tbody>
<?php foreach($rows as$row):?><tr><?php if($view==='received'):?><td><?=e(reader_utc_label($row['created_at']))?><br><a href="<?=url('/write/readers/enquiries/'.$row['id'])?>"><?=e($row['reference'])?></a></td><td><?=e(trim($row['first_name'].' '.$row['last_name']))?><br><?=e($row['email'])?></td><td><?php if($ack=$row['acknowledgement']):?><?=e(correspondence_status($ack['status']))?><br><a href="<?=url('/write/correspondence?view=outgoing&q='.$ack['id'])?>">Email #<?=(int)$ack['id']?></a><?php else:?>Not queued / held for review<?php endif;?></td><td><?=(int)$row['recorded_responses']?> manually confirmed replies<br><?=e(reader_utc_label($row['last_response_at']))?><br><a href="<?=url('/write/readers/enquiries/'.$row['id'])?>">Enquiry history →</a></td>
<?php elseif($view==='outgoing'):?><td>#<?=(int)$row['id']?><br><?=e($row['created_at']??'')?></td><td><?=e($row['recipient'])?><br><strong><?=e($row['subject'])?></strong></td><td><?=e(correspondence_status($row['status']))?><br><?=e($row['sent_at']??'')?></td><td><?php if(!empty($row['provider_id'])):?><small>Provider reference: <?=e($row['provider_id'])?></small><br><?php endif;?><details><summary>View saved branded email</summary><iframe title="Saved email #<?=(int)$row['id']?>" sandbox referrerpolicy="no-referrer" loading="lazy" src="<?=url('/write/correspondence/email/'.$row['id'].'/preview')?>" style="width:100%;min-width:280px;height:540px;border:1px solid #d8e4e9"></iframe></details></td>
<?php else:?><td><?=e(date('j M Y, H:i',(int)($row['at']??0)))?><br><?=e($row['account']??'')?></td><td><?=e($row['recipient']??'Not recorded in older draft history')?><br><?=e($row['subject']??'')?></td><td><?=e(correspondence_status($row['status']??''))?><?php if(!empty($row['provider_draft_id'])):?><br>Draft reference: <?=e($row['provider_draft_id'])?><?php endif;?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div>
<?php if(!$rows):?><section class="desk-empty"><h2>No records in this view.</h2><p>Real correspondence appears when received, queued or explicitly drafted. No sample messages are added to live records.</p></section><?php endif;?>
<nav class="desk-actions" aria-label="Log pages"><?php if($page>1):?><a class="desk-button" href="?<?=e(http_build_query(['view'=>$view,'q'=>$search,'status'=>$status,'page'=>$page-1]))?>">Previous</a><?php endif;?><?php if($page<$pages):?><a class="desk-button" href="?<?=e(http_build_query(['view'=>$view,'q'=>$search,'status'=>$status,'page'=>$page+1]))?>">Next</a><?php endif;?></nav>
<section class="desk-callout"><strong>Delivery evidence matters.</strong><p>Queued is not sent. Provider acceptance does not prove inbox placement or reading. Unconfirmed outcomes are not automatically resent. Manually sent replies remain labelled as owner-recorded, not provider-verified.</p></section></main>
